import 'fake-indexeddb/auto';
import {it,expect,afterEach} from 'vitest';
import {writeFileSync} from 'node:fs';
import {createProject,createEntity,newId} from '../src/domain/model';
import {createWorldSnapshot} from '../src/domain/world';
import {ScenarioStore} from '../src/storage/store';
import {closureAttachmentMetadata,exportScenario,inspectScenarioData,assetPath} from '../src/storage/archive';
import {sha256} from '../src/storage/json';
const root='/tmp/shinariokanri-independent-rb09-35d34a8/independent',stores:ScenarioStore[]=[];
afterEach(async()=>{for(const s of stores.splice(0))await s.deleteDatabase();});
function target(){const s=new ScenarioStore({databaseName:'independent-world-closure-'+newId(),accountId:newId()});stores.push(s);return s;}
async function setup(){const bytes=new TextEncoder().encode('推移依存の旧素材😀'),hash=await sha256(bytes),w2=createProject('旧版素材を持つ世界B'),asset=createEntity(w2.projectId,'attachment','旧素材',{mediaType:'text/plain',contentHash:hash,byteSize:bytes.length,assetPath:assetPath(hash,'text/plain'),displayName:'old.txt',stage:'final'});asset.status='confirmed';w2.entities.push(asset);const fixed2=await createWorldSnapshot(w2,'B旧版'),pin2=fixed2.snapshots[0],w1=createProject('世界A');w1.worldReferences.push({projectId:w2.projectId,immutableSnapshotId:pin2.id,contentHash:pin2.contentHash});const fixed1=await createWorldSnapshot(w1,'A採用版'),pin1=fixed1.snapshots[0],p=createProject('推移固定世界の作品');p.worldReferences.push({projectId:w1.projectId,immutableSnapshotId:pin1.id,contentHash:pin1.contentHash});const registry={[pin1.id]:fixed1,[pin2.id]:fixed2},changed=structuredClone(fixed2),newBytes=new TextEncoder().encode('採用しない現在素材'),newHash=await sha256(newBytes);Object.assign(changed.entities.find(e=>e.id===asset.id)!.data,{contentHash:newHash,byteSize:newBytes.length,assetPath:assetPath(newHash,'text/plain')});const newWorld=await createWorldSnapshot(changed,'B新稿');return {p,registry,pin1,pin2,hash,bytes,newHash,newWorld};}
it('R9WV01 captures both transitive pins and only their old material rather than an unadopted current edition',async()=>{const f=await setup(),metadata=closureAttachmentMetadata(f.p,{...f.registry,[f.newWorld.snapshots.at(-1)!.id]:f.newWorld});expect(metadata.map(m=>m.contentHash)).toEqual([f.hash]);writeFileSync(`${root}/fixtures/R9WV01.json`,JSON.stringify({...f,bytes:[...f.bytes],metadata},null,2)+'\n');});
it('R9WV02 transitive expected descriptor absence or mismatch refuses instead of borrowing another world edition',async()=>{const f=await setup();expect(()=>closureAttachmentMetadata(f.p,{[f.pin1.id]:f.registry[f.pin1.id]})).toThrow();const wrong=structuredClone(f.registry);wrong[f.pin2.id].snapshots[0].contentHash='0'.repeat(64);expect(()=>closureAttachmentMetadata(f.p,wrong)).toThrow();writeFileSync(`${root}/fixtures/R9WV02.json`,JSON.stringify({missingTransitiveRefused:true,mismatchingExpectedHashRefused:true},null,2)+'\n');});
it('R9WV03 complete archive new and clone retain both transitive old pins and actual material bytes, then cold reread',async()=>{const f=await setup(),bytes=await exportScenario(f.p,{worlds:f.registry,loadAsset:async hash=>hash===f.hash?f.bytes:undefined}),prepared=await inspectScenarioData(bytes);expect(Object.keys(prepared.worlds).sort()).toEqual(Object.keys(f.registry).sort());const results=[];for(const mode of ['new','clone'] as const){const s=target(),result=await s.importScenario(prepared,{mode});expect(await s.getAsset(f.hash)).toEqual(f.bytes);expect((await s.getProject(result.project.projectId))!.worldReferences).toEqual(f.p.worldReferences);s.close();const cold=new ScenarioStore({databaseName:(s as unknown as {db:{name:string}}).db.name,accountId:s.accountId!});stores.push(cold);expect(await cold.getAsset(f.hash)).toEqual(f.bytes);const again=await inspectScenarioData(await cold.exportProject(result.project.projectId));expect(Object.keys(again.worlds).sort()).toEqual(Object.keys(f.registry).sort());expect(again.worlds[f.pin2.id].snapshots.find(x=>x.id===f.pin2.id)!.contentHash).toBe(f.pin2.contentHash);results.push({mode,id:result.project.projectId,oldWorldHash:again.worlds[f.pin2.id].snapshots.find(x=>x.id===f.pin2.id)!.contentHash,actualBytes:[...(await cold.getAsset(f.hash))!]});}writeFileSync(`${root}/fixtures/R9WV03.json`,JSON.stringify({results,sourceProject:f.p,worlds:f.registry},null,2)+'\n');writeFileSync(`${root}/fixtures/transitive-old-world.scenario`,bytes);});
